void sms_detail_draft_key_event(uint32_t key,lv_obj_t * ui_Screen)
{
    ui_screen_sms_detail_draft_obj_t * p_screen_param;

    p_screen_param      = (ui_screen_sms_detail_draft_obj_t *) lv_obj_get_user_data(ui_Screen);

    //__inf("sms_menu_key_event key:%d,child_id:%d,child_cnt:%d\r\n",key,child_id,child_cnt);
    switch (key)
    {
        case LV_KEY_UP:
            {
                lv_coord_t      scroll_y;

                scroll_y            = lv_obj_get_scroll_y(p_screen_param->obj_label_content);

                if (scroll_y > 0)
                    scroll_y -= 200;

                lv_obj_scroll_to_y(p_screen_param->obj_label_content,scroll_y,LV_ANIM_OFF);
                }
            break;

        case LV_KEY_DOWN:
            {
                lv_coord_t      scroll_y;

                scroll_y            = lv_obj_get_scroll_y(p_screen_param->obj_label_content);
                scroll_y            += 200;
                lv_obj_scroll_to_y(p_screen_param->obj_label_content,scroll_y,LV_ANIM_OFF);
                }
            break;

        case APP_KEY_VALUE_TOP_LEFT:
            {
                alv_am_win_enter(NULL,"detail_draft_option",(void *) ui_Screen);
                }
            break;

        case APP_KEY_VALUE_TOP_RIGHT:
            {
                alv_am_win_exit_current(NULL);
                }
            break;

        case LV_KEY_ENTER:
            {

                }
            break;

        case LV_KEY_END:
            alv_am_app_exit_action_all();
            break;
        }
}


