static void remind_timer_callback_sms_detail_draft(screen_remind_param_t * p_screen_remind_param)
{
    detail_draft_win_param_t * p_param;

    lv_obj_t *      ui_screen;

    p_param             = p_screen_remind_param->user_data;

    ui_screen           = ui_ScreenSmsDetailDraft_screen_init(&p_param->enter_param);

    p_param->ui_main    = ui_screen;

    if (p_param->focus_status == 0)
        return;

    lv_disp_load_scr(ui_screen);

    {
        ui_screen_sms_detail_draft_obj_t * p_screen_param;

        p_screen_param      = (ui_screen_sms_detail_draft_obj_t *) lv_obj_get_user_data(ui_screen);

        app_fp_play_tts_sms(lv_label_get_text(p_screen_param->obj_label_content));

        }

}




lv_obj_t * ui_ScreenSmsDetailDraft_screen_active(lv_obj_t * win,void * param)
{
    screen_remind_param_t screen_remind_param;
    lv_obj_t *      ui_screen;
    detail_draft_win_param_t * p_param;

    p_param             = lv_mem_alloc(sizeof(detail_draft_win_param_t));
    p_param->ui_remind  = NULL;
    p_param->ui_main    = NULL;
    p_param->focus_status = 0;
    memcpy(&p_param->enter_param,param,sizeof(sms_detail_ui_enter_param_t));


    ui_screen_remind_param_init(&screen_remind_param);
    screen_remind_param.str = "正打开";
    screen_remind_param.tiemr_delay = 500;
    screen_remind_param.fun = (remind_timer_callback_fun_t) remind_timer_callback_sms_detail_draft;
    screen_remind_param.user_data = p_param;
    screen_remind_param.self_destory_flag = 0;
    screen_remind_param.key_exit_enable = 0;

    ui_screen           = ui_screen_remind_init(&screen_remind_param);

    p_param->ui_remind  = ui_screen;

    lv_obj_set_user_data(win,p_param);

    return ui_screen;
}


void ui_ScreenSmsDetailDraft_screen_deactive(lv_obj_t * win,void * param)
{
    detail_draft_win_param_t * p_param;

    p_param             = (detail_draft_win_param_t *) lv_obj_get_user_data(win);
    ui_screen_remind_uninit(p_param->ui_remind);
    ui_ScreenSmsDetailDraft_screen_uninit();

    lv_mem_free(p_param);

    lv_obj_set_user_data(win,NULL);
}


void ui_ScreenSmsDetailDraft_win_focus(lv_obj_t * win,void * param)
{
    detail_draft_win_param_t * p_param;

    p_param             = (detail_draft_win_param_t *) lv_obj_get_user_data(win);
    lv_obj_t *      ui_screen = NULL;

    if (p_param->ui_main)
        ui_screen = p_param->ui_main;
    else if (p_param->ui_remind)
        ui_screen = p_param->ui_remind;

    if (ui_screen) {
        lv_disp_load_scr(ui_screen);
        }

    if (ui_screen == p_param->ui_remind) {
        ui_screen_sms_detail_draft_obj_t * p_screen_param;

        p_screen_param      = (ui_screen_sms_detail_draft_obj_t *) lv_obj_get_user_data(ui_screen);

        app_fp_play_tts_sms(lv_label_get_text(p_screen_param->obj_label_content));

        }

    p_param->focus_status = 1;
}

void ui_ScreenSmsDetailDraft_win_defocus(lv_obj_t * win,void * param)
{
    detail_draft_win_param_t * p_param;

    p_param             = lv_obj_get_user_data(win);
    p_param->focus_status = 0;
}

